// T-783 (P3-16): THIRD-PARTY-NOTICES.txt travels with every install (tauri.conf.json bundle.resources) and the About panel
// shows it. The file is generated by scripts/notices.mjs; this module only reads it back.
use std::path::{Path, PathBuf};
use tauri::path::BaseDirectory;
use tauri::Manager;

/// The file's name inside the install's resource folder.
pub const NOTICES_FILE: &str = "THIRD-PARTY-NOTICES.txt";

/// The first of `places` that holds the notices file, read as text. The error names every place it looked.
pub fn read_first(places: &[PathBuf]) -> Result<String, String> {
    for p in places {
        if let Ok(text) = std::fs::read_to_string(p) {
            return Ok(text);
        }
    }
    let looked: Vec<String> = places.iter().map(|p| p.display().to_string()).collect();
    Err(format!("{NOTICES_FILE} was not found (looked in {})", looked.join(", ")))
}

fn places(resolved: Option<PathBuf>, source_tree: Option<&Path>) -> Vec<PathBuf> {
    // A run from the source tree (tauri dev) may not have staged the resource yet; the committed copy is the same file.
    resolved.into_iter().chain(source_tree.map(|d| d.join("resources").join(NOTICES_FILE))).collect()
}

/// The licence notices of the open-source code in this build, for the About panel.
#[tauri::command(async)]
pub fn third_party_notices(app: tauri::AppHandle) -> Result<String, String> {
    let resolved = app.path().resolve(NOTICES_FILE, BaseDirectory::Resource).ok();
    let tree = if cfg!(debug_assertions) { Some(Path::new(env!("CARGO_MANIFEST_DIR"))) } else { None };
    read_first(&places(resolved, tree))
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn t783_the_committed_file_is_there_and_names_the_big_dependencies() {
        let p = Path::new(env!("CARGO_MANIFEST_DIR")).join("resources").join(NOTICES_FILE);
        let text = read_first(&[p]).expect("src-tauri/resources/THIRD-PARTY-NOTICES.txt is committed");
        assert!(text.starts_with("THIRD-PARTY NOTICES"));
        for name in ["tauri ", "serde ", "react "] {
            assert!(text.contains(&format!("  {name}")), "{name} is listed");
        }
        assert!(text.contains("Permission is hereby granted"), "carries the MIT text");
    }

    #[test]
    fn t783_the_first_place_that_has_it_wins_and_a_miss_names_every_place() {
        let dir = std::env::temp_dir().join(format!("kolux-notices-{}", std::process::id()));
        std::fs::create_dir_all(&dir).unwrap();
        let there = dir.join("n.txt");
        std::fs::write(&there, "hello").unwrap();
        let gone = dir.join("gone.txt");
        assert_eq!(read_first(&[gone.clone(), there.clone()]).unwrap(), "hello");
        let err = read_first(&[gone.clone(), dir.join("also.txt")]).unwrap_err();
        assert!(err.contains("gone.txt") && err.contains("also.txt") && err.contains(NOTICES_FILE), "{err}");
        std::fs::remove_dir_all(&dir).unwrap();
    }

    #[test]
    fn t783_a_source_tree_run_falls_back_to_the_committed_copy() {
        let tree = Path::new(env!("CARGO_MANIFEST_DIR"));
        let list = places(Some(PathBuf::from("Z:/nowhere/THIRD-PARTY-NOTICES.txt")), Some(tree));
        assert_eq!(list.len(), 2);
        assert!(read_first(&list).unwrap().starts_with("THIRD-PARTY NOTICES"));
        assert_eq!(places(None, None).len(), 0);
    }
}
